// Cuibhreanncuraidh, the champion's helping (generated by tools/integration/gen_bridges.py).
// Eating a dish of the right kind gives a timed buff; a new feast buff is refused while the last still runs.
const FEASTS = [["c:foods/cooked_meat", [["minecraft:strength", 180, 0], ["minecraft:resistance", 180, 0]]], ["c:foods/cooked_fish", [["minecraft:water_breathing", 240, 0], ["minecraft:luck", 240, 0]]], ["c:foods/pie", [["minecraft:regeneration", 60, 0], ["minecraft:absorption", 180, 0]]], ["c:drinks/honey", [["minecraft:regeneration", 90, 0]]], ["c:drinks/milk", [["minecraft:haste", 120, 0]]]]
ItemEvents.foodEaten(event => {
  try {
    let p = event.player, now = p.level.getGameTime(), until = p.persistentData.getLong('diaithir_feast_until')
    if (now < until) return
    for (let f of FEASTS) {
      if (!event.item.hasTag(f[0])) continue
      let longest = 0
      for (let e of f[1]) { p.potionEffects.add(e[0], e[1] * 20, e[2]); longest = Math.max(longest, e[1] * 20) }
      p.persistentData.putLong('diaithir_feast_until', now + longest)
      return
    }
  } catch (err) { console.error('[integration] feast buff failed: ' + err) }
})
